updateFoam(dt) {
  const decay = Math.exp(-2.2 * dt);
  for (let i = 0; i < this.numParticles; i++) {
    const t = Math.max(0, this.turb[i] - 0.4);
    this.foam[i] = Math.min(1, this.foam[i] * decay + t * 0.3);
  }
}

arguments.new_string:
updateFoam(dt) {
  const decay = Math.exp(-3.0 * dt);
  for (let i = 0; i < this.numParticles; i++) {
    const t = Math.max(0, this.turb[i] - 0.75);
    this.foam[i] = Math.min(1, this.foam[i] * decay + t * 0.22);
  }
}
